def count_bitonic_subseqs(nums):
    n = len(nums)
    if n < 3:
        return 0
    dp_inc = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp_inc[i] += dp_inc[j]

    dp_dec = [1] * n
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            if nums[j] < nums[i]:
                dp_dec[i] += dp_dec[j]

    total = 0
    for i in range(n):
        total += (dp_inc[i] - 1) * (dp_dec[i] - 1)
    return total

