def subset_max_gcd(nums):
    n = len(nums)
    if n < 2:
        return 0
    abs_nums = [abs(x) for x in nums]
    max_val = max(abs_nums) if n > 0 else 0
    if max_val == 0:
        return 0
    zeros = abs_nums.count(0)
    candidate1 = max_val if zeros > 0 else 0
    non_zero = [x for x in abs_nums if x != 0]
    if len(non_zero) < 2:
        return candidate1
    candidate2 = 0
    for d in range(max_val, 0, -1):
        count = 0
        for num in non_zero:
            if num % d == 0:
                count += 1
                if count >= 2:
                    candidate2 = d
                    break
        if candidate2 != 0:
            break
    return max(candidate1, candidate2)

